func writeOutput(f *os.File, results [][]float64, format string) {
        switch format {
        case "csv":
                writer := csv.NewWriter(f)
                header := make([]string, len(results[0]))
                for i := range header {
                        header[i] = fmt.Sprintf("output_%d", i)
                }
                writer.Write(header)
                for _, row := range results {
                        record := make([]string, len(row))
                        for j, val := range row {
                                record[j] = strconv.FormatFloat(val, 'f', -1, 64)
                        }
                        writer.Write(record)
                }
                writer.Flush()
        case "json":
                type Prediction struct {
                        Outputs []float64 `json:"outputs"`
                }
                type Result struct {
                        Predictions []Prediction `json:"predictions"`
                }
                r := Result{}
                for _, row := range results {
                        r.Predictions = append(r.Predictions, Prediction{Outputs: row})
                }
                enc := json.NewEncoder(f)
                enc.SetIndent("", "  ")
                enc.Encode(r)
        }
}
